INTRX1_HANDLER:	; 1F736
	push xiz
	push xiy
	push xix
	push xhl
	push xde
	push xbc
	push xwa
	ld_sd8b C, 0xD4
	ld_sd8b A, 0xD5
	and a, 0x1C	; 0001 1100
	jr z, Serial1_RX_NoError

	; serial comms error happened:
	ldmm_sd8b 0xD5, 0x36, 0x10	; LD (1036h), (SC1CR)
	jr Serial1_RX_Exit

Serial1_RX_NoError:	; 01F74Fh
	bitda 2, 4148	; Check if RX enabled
	jr z, Serial1_RX_Exit
	ld xwa, 0xE00	; Ring buffer descriptor at 0x0E00
	calr SAVE_BYTE_TO_RING_BUFFER

Serial1_RX_Exit:	; 01F75Dh
	pop xwa
	pop xbc
	pop xde
	pop xhl
	pop xix
	pop xiy
	pop xiz
	reti


; ----------------------------------------------------------------------------
; INTTX1_HANDLER - Serial Port 1 Transmit Complete Interrupt
; Entry: None
; Notes: Sends next byte from TX ring buffer (0x1016) or 0xFE if sync needed
; ----------------------------------------------------------------------------
INTTX1_HANDLER:	; 01F765h
	push xiz
	push xiy
	push xix
	push xhl
	push xde
	push xbc
	push xwa
	bitda 0, 4148	; Check sync flag
	jr z, Serial1_TX_Normal
	resda 0, 4148
	ldio 0xD4, 0xFE	; Send sync byte
	jr Serial1_TX_CheckEmpty

Serial1_TX_Normal:	; 01F77Bh
	ld xwa, 0x1016	; TX ring buffer descriptor
	calr READ_BYTE_FROM_RING_BUFFER
	cp hl, 0xFFFF	; Buffer empty?
	jr z, Serial1_TX_CheckEmpty
	st_dd8b L, 0xD4	; Send byte

Serial1_TX_CheckEmpty:	; 01F78Ch
	bitda 0, 4148
	jr nz, Serial1_TX_Exit
	ld xwa, 0x1016
	calr RING_BUFFER_HAS_OVERRUN
	cp hl, 0xFFFF	; Buffer empty?
	jr nz, Serial1_TX_Exit
	ldio 0xEB, 0xFD	; Disable TX interrupt

Serial1_TX_Exit:	; 01F7A3h
	pop xwa
	pop xbc
	pop xde
	pop xhl
	pop xix
	pop xiy
	pop xiz
	reti


; returns:
; HL = 0ffffh (True)
; HL = 0000h (False)
;
RING_BUFFER_HAS_OVERRUN:	; 1F7AB
	lds hl, 0
	ld xbc, (xwa + 12)	; current_read_pointer
	cp xbc, (xwa + 8)	; current_write_pointer
	ret nz
	ldw hl, 0xFFFF
	ret


; ----------------------------------------------------------------------------
; READ_BYTE_FROM_RING_BUFFER - Read a byte from a ring buffer
; Entry: XWA = ring buffer descriptor pointer
; Exit:  L = byte read, HL = 0 on success
;        HL = 0xFFFF if buffer empty
; Notes: Ring buffer descriptor format:
;        +0x00: buffer_start pointer
;        +0x04: buffer_end pointer
;        +0x08: write_pointer
;        +0x0C: read_pointer
;        +0x14: available_bytes count
; ----------------------------------------------------------------------------
READ_BYTE_FROM_RING_BUFFER:	; 01F7B9h
	ldw hl, 0xFFFF
	lda xde, (xwa + 8)	; current_write_pointer
	ld xbc, (xde)
	ld xix, xbc
	cp (xwa + 12), xbc	; current_read_pointer
	ret z	; Buffer empty
	ld l, (xbc)	; Read byte
	cp xbc, (xwa + 4)	; buffer_end
	jr nz, RingBuf_Read_NoWrap
	ld xix, (xwa)	; buffer_start - wrap around
	jr RingBuf_Read_Update

RingBuf_Read_NoWrap:	; 01F7D3h
	inc 1, xix

RingBuf_Read_Update:	; 01F7D5h
	ld (xde), xix	; Update write pointer
	incm 1, (xwa + 20)	; Increment available count
	extz hl
	ret

; ----------------------------------------------------------------------------
; SAVE_BYTE_TO_RING_BUFFER - Write a byte to a ring buffer
; Entry: XWA = ring buffer descriptor pointer
;        C = byte to write
; Exit:  HL = available bytes remaining
; Notes: Returns without writing if buffer full (available == 0)
; ----------------------------------------------------------------------------
SAVE_BYTE_TO_RING_BUFFER:	; 01F7DDh
	lda xix, (xwa + 20)
	ld hl, (xix)	; Get available count
	lda xde, (xwa + 12)
	ld xiy, (xde)
	cps hl, 0
	ret z	; Buffer full
	ld (xiy), c	; Write byte
	cp xiy, (xwa + 4)
	jr nz, RingBuf_Write_NoWrap
	ld xiy, (xwa)	; Wrap around
	jr RingBuf_Write_Update

RingBuf_Write_NoWrap:	; 01F7F6h
	inc 1, xiy

RingBuf_Write_Update:	; 01F7F8h
	ld (xde), xiy	; Update read pointer
	ld hl, (xix)
	dec 1, hl	; Decrement available count
	ld (xix), hl
	ret

; ----------------------------------------------------------------------------
; Serial1_Enable_TX_Interrupt - Enable serial port 1 TX interrupt
; Entry: None
; Notes: Used to start transmission when data is queued
; ----------------------------------------------------------------------------
Serial1_Enable_TX_Interrupt:	; 01F801h
	push	sr
	ei 6
	ldio 0xEB, 0xDD
	pop	sr
	ret

Serial1_BaudRate_Config_Table:
	.byte 0x02, 0x06, 0x06, 0x08, 0xeb, 0xfd, 0x03, 0x0e

Serial1_CommandHandler_RX_F4F5:
	cp a, 0xF5
	jr z, Serial1_F5_BaudRate_Switch
	cp a, 0xF4
	ret nz
	stdi8 4152, 3
	setda 2, 4148
	ei 6
	ldio 0xD6, 0x2B
	ei 0
	ret

Serial1_F5_BaudRate_Switch:
	stdi8 4152, 2
	setda 2, 4148
	ret

Audio_CheckQueuedData_Send:
	ldda32 xwa, 4140
	ldda32 xbc, 4160
	ld xde, xbc
	sub xde, xwa
	cp xde, 0x87
	ret c
	stda32 4140, xbc
	setda 0, 4148
	calr Serial1_Enable_TX_Interrupt
	ret

Audio_DMA_RingBuffer_To_Maincpu:
	pushw iz
	lds iz, 0

Audio_DMA_RingBuf_ReadLoop:
	ld xwa, 0xE00
	calr READ_BYTE_FROM_RING_BUFFER
	cp hl, 0xFFFF
	jr z, Audio_DMA_RingBuf_CheckSend
	ld wa, iz
	inc 1, iz
	lda_d16 xbc, 1536
	extz xwa
	add xwa, xbc
	ld (xwa), l
	cp iz, 0x400
	jr c, Audio_DMA_RingBuf_ReadLoop

Audio_DMA_RingBuf_CheckSend:
	cps iz, 0
	jr z, Audio_DMA_RingBuf_Done
	ei 0
	lds wa, 4
	ld bc, iz
	ld xde, 0x600
	call InterCPU_DMA_Send

Audio_DMA_RingBuf_Done:
	popw iz
	ret

Serial1_DataTransmit_Loop:
	ld a, (xsp + 4)
	decm8 1, (xsp + 4)
	cps a, 0
	jr z, Serial1_TX_Done

Serial1_TX_LoopBody:
	bitda 2, 4148
	jr nz, Serial1_TX_ViaRingBuf
	ld xwa, (xsp + 6)
	ldb_spi C, 0xE0
	ld (xsp + 6), xwa
	extz bc
	ld wa, bc
	calr Serial1_CommandHandler_RX_F4F5
	jr Serial1_TX_CheckNext

Serial1_TX_ViaRingBuf:
	ld xwa, (xsp + 6)
	ldb_spi C, 0xE0
	ld (xsp + 6), xwa
	extz bc
	ld xwa, 0x1016
	calr SAVE_BYTE_TO_RING_BUFFER
	calr Serial1_Enable_TX_Interrupt

Serial1_TX_CheckNext:
	ld a, (xsp + 4)
	decm8 1, (xsp + 4)
	cps a, 0
	jr nz, Serial1_TX_LoopBody

Serial1_TX_Done:
	lds hl, 0
	ret

Audio_Process_Final:
	push	sr
	ei 6
	calr Audio_DMA_RingBuffer_To_Maincpu
	pop	sr
	jrl Audio_CheckQueuedData_Send

INIT_RING_BUFFERS:
	stdi8 4148, 0
	setda 0, 4148
	stdi8 4152, 0
	ld xiy, 0xF434
	ld xix, 0xE00
	ldw bc, 0xB
	ldirw
	ld xiy, 0xF44A
	ld xix, 0x1016
	ldw bc, 0xB
	ldirw
	ei 6	; <-------  1f90b
	ldio 0xD6, 0x29
	ldio 0xD5, 0x00
	ldio 0xD7, 0x0A
	ldio 0xEB, 0x5D
	ldio 0xD4, 0xFE
	ei 0
	ret

Serial1_Config_Constants:
	.byte 0x05, 0x0e, 0x68, 0x01, 0x0e


